<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$id=(int)($_GET['id']??0);$row=$id?$pdo->query("SELECT * FROM fornecedores WHERE id=$id")->fetch():null;$pageTitle=$row?'Editar fornecedor':'Novo fornecedor';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$d=[trim($_POST['nome']??''),trim($_POST['cpf_cnpj']??''),trim($_POST['telefone']??''),trim($_POST['email']??''),trim($_POST['endereco']??''),trim($_POST['contato']??''),trim($_POST['observacoes']??'')];if($d[0]==='')$error='Nome é obrigatório.';else{if($id)$pdo->prepare('UPDATE fornecedores SET nome=?,cpf_cnpj=?,telefone=?,email=?,endereco=?,contato=?,observacoes=?,atualizado_em=? WHERE id=?')->execute([...$d,now(),$id]);else{$pdo->prepare('INSERT INTO fornecedores(nome,cpf_cnpj,telefone,email,endereco,contato,observacoes,ativo,criado_em,atualizado_em) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([...$d,1,now(),now()]);$id=(int)$pdo->lastInsertId();}log_action($id?'alteração de fornecedor':'criação de fornecedor','fornecedores',$id);flash('success','Fornecedor salvo com sucesso.');redirect('index.php');}}include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1><?=e($pageTitle)?></h1><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field col-6"><label>Nome/Razão social</label><input name="nome" required value="<?=e($row['nome']??'')?>"></div><div class="field col-3"><label>CPF/CNPJ</label><input name="cpf_cnpj" value="<?=e($row['cpf_cnpj']??'')?>"></div><div class="field col-3"><label>Telefone</label><input name="telefone" value="<?=e($row['telefone']??'')?>"></div><div class="field col-6"><label>E-mail</label><input type="email" name="email" value="<?=e($row['email']??'')?>"></div><div class="field col-6"><label>Contato</label><input name="contato" value="<?=e($row['contato']??'')?>"></div><div class="field col-12"><label>Endereço</label><input name="endereco" value="<?=e($row['endereco']??'')?>"></div><div class="field col-12"><label>Observações</label><textarea name="observacoes"><?=e($row['observacoes']??'')?></textarea></div></div><div class="form-actions"><button class="btn primary">Salvar</button></div></form></div><?php include __DIR__.'/../../includes/footer.php'; ?>
